<script setup>
import {ref,computed,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useIrrigation} from '../../data/runtime.js'
import {useClock} from '../../composables/useClock.js'
import {useListState} from '../../composables/useListState.js'
import BaseModal from '../../components/BaseModal.vue'
import DataTable from '../../components/DataTable.vue'
import Pagination from '../../components/Pagination.vue'
import StatusBadge from '../../components/StatusBadge.vue'
import {stages,triggers,columns,ordered,localInput,isoInput,setPlanSuggestion} from './operationUi.js'
const r=useIrrigation(),route=useRoute(),router=useRouter(),clock=useClock(),state=useListState('strategies',{filters:{crop:(r.state.entities.CropSeason??[]).find(s=>s.status==='ENABLED')?.crop||'',stage:(r.state.entities.CropSeason??[]).find(s=>s.status==='ENABLED')?.stage||'',status:''}}),filters=ref({...state.filters}),modal=ref(false),selected=ref(null),asOf=ref(''),points=ref({}),result=ref(null),busy=ref(false),failure=ref('')
const crops=computed(()=>[...new Set((r.state.entities.Strategy??[]).map(s=>s.crop))]),rows=computed(()=>ordered((r.state.entities.Strategy??[]).filter(s=>Object.entries(state.filters).every(([k,v])=>!v||s[k]===v)),state.sort)),visible=computed(()=>rows.value.slice((state.page-1)*15,state.page*15)),zones=computed(()=>(r.state.entities.IrrigationZone??[]).filter(z=>selected.value?.zoneIds.includes(z.zoneId)))
watch(()=>[asOf.value,JSON.stringify(points.value)],()=>{result.value=null})
const cols=columns([['number','序号',65],['strategyId','策略编号',180],['name','策略名称'],['triggerMode','触发',90],['thresholdVwc','阈值%VWC',105],['targetVolumeM3','目标m³',100],['status','状态',95],['version','版本',85],['actions','操作',140]])
function edit(s){state.selectedId=s?.strategyId;router.push({path:s?'/strategies/'+s.strategyId+'/edit':'/strategies/new',query:{from:route.fullPath}})}
function open(s){selected.value=s;points.value={};asOf.value=localInput(clock.displayNow.value);result.value=null;failure.value='';modal.value=true}
async function simulate(){busy.value=true;failure.value='';result.value=null;try{if((r.state.entities.Strategy??[]).find(s=>s.strategyId===selected.value.strategyId)?.version!==selected.value.version)throw new Error('策略版本已变化，请关闭试算后重新打开');if(zones.value.some(z=>!points.value[z.zoneId]))throw new Error('请为每个分区显式选择代表点位');result.value=await r.query('simulation',{strategyId:selected.value.strategyId,asOf:isoInput(asOf.value),representativePointByZone:points.value})}catch(e){failure.value=e.message}finally{busy.value=false}}
function toPlan(){const assessments=result.value.zoneAssessments.filter(x=>x.eligible);setPlanSuggestion({strategyId:selected.value.strategyId,name:selected.value.name+'轮灌计划',steps:assessments.map((a,i)=>({zoneId:a.zoneId,order:i+1,targetVolumeM3:a.targetVolumeM3,expectedFlowM3h:r.getIndex().byId.IrrigationZone.get(a.zoneId)?.designFlowM3h,maxDurationMin:selected.value.maxDurationMin}))});modal.value=false;router.push({path:'/plans/new',query:{suggestion:'1',from:route.fullPath}})}
</script>
<template><div class="page-stack strategy-list"><form class="panel filters" @submit.prevent="state.filters={...filters};state.page=1"><label class="filter-field">作物<select v-model="filters.crop"><option value="">全部</option><option v-for="c in crops" :key="c">{{c}}</option></select></label><label class="filter-field">阶段<select v-model="filters.stage"><option value="">全部</option><option v-for="(n,k) in stages" :key="k" :value="k">{{n}}</option></select></label><label class="filter-field">状态<select v-model="filters.status"><option value="">全部</option><option value="ENABLED">启用</option><option value="DISABLED">停用</option></select></label><button class="btn btn-primary">查询</button><button type="button" class="btn" :disabled="!r.can('STRATEGY_CREATE')" @click="edit()">新增策略</button></form><section class="panel strategy-summary"><div><strong>{{rows.length}}</strong> 项策略</div><div>启用 <strong>{{rows.filter(x=>x.status==='ENABLED').length}}</strong></div><div>停用 <strong class="danger">{{rows.filter(x=>x.status==='DISABLED').length}}</strong></div></section><section class="panel strategy-table"><DataTable :loading="!r.state.ready" :columns="cols" :rows="visible" row-key="strategyId" :selected-id="state.selectedId" :sort="state.sort" @update:sort="state.sort=$event" @row-click="state.selectedId=$event.strategyId"><template #cell-number="{index}">{{(state.page-1)*15+index+1}}</template><template #cell-triggerMode="{value}">{{triggers[value]||value}}</template><template #cell-thresholdVwc="{row}">{{row.triggerMode==='MOISTURE'?Number(row.thresholdVwc).toFixed(1):'—'}}</template><template #cell-targetVolumeM3="{value}">{{Number(value).toFixed(1)}}</template><template #cell-status="{value}"><StatusBadge :status="value"/></template><template #cell-version="{value}">V{{value}}</template><template #cell-actions="{row}"><button class="btn-link" :disabled="!r.can('STRATEGY_UPDATE',row)" @click.stop="edit(row)">编辑</button>　|　<button class="btn-link" @click.stop="open(row)">试算</button></template></DataTable><Pagination v-model="state.page" :total="rows.length"/></section><BaseModal v-model="modal" title="策略试算" :busy="busy" width="760px"><template v-if="selected"><p>{{selected.strategyId}} · {{selected.name}} · V{{selected.version}}</p><label class="filter-field">试算时刻<input v-model="asOf" :disabled="busy" type="datetime-local" step="1"/></label><label v-for="z in zones" :key="z.zoneId" class="filter-field simulation-point">{{z.name}}代表点位<select v-model="points[z.zoneId]" :disabled="busy"><option :value="undefined">请选择代表点位</option><option v-for="p in (r.state.entities.Point??[]).filter(p=>p.zoneId===z.zoneId&&p.kind==='SOIL_MOISTURE')" :key="p.pointId" :value="p.pointId">{{p.name}} · {{p.depthCm}}cm · {{p.pointId}}</option></select></label><p v-if="failure" class="error-text" role="alert">{{failure}}</p><div v-if="result" class="simulation-results"><div v-for="(a,i) in result.zoneAssessments" :key="a.zoneId||i"><strong>{{r.getIndex().byId.IrrigationZone.get(a.zoneId)?.name||a.zoneId}}</strong>：{{a.eligible?'建议灌溉 '+a.targetVolumeM3+'m³':'不建议'}} · {{a.reason}}<pre v-if="a.moistureEvidence">{{JSON.stringify(a.moistureEvidence,null,2)}}</pre></div></div></template><template #footer><button class="btn" :disabled="busy" @click="modal=false">取消</button><button class="btn btn-primary" :disabled="busy" @click="simulate">{{busy?'试算中…':'试算'}}</button><button v-if="result?.zoneAssessments.some(x=>x.eligible)" class="btn" :disabled="!r.can('PLAN_CREATE')" @click="toPlan">转计划草稿</button></template></BaseModal></div></template>
<style scoped>.strategy-list{gap:20px}.strategy-list .filters{padding:19px 20px;gap:26px}.strategy-list .filter-field{flex:1}.strategy-list .filters>.btn{min-width:147px}.strategy-summary{display:flex;align-items:center;height:86px;padding:18px 0}.strategy-summary>div{flex:1;text-align:center}.strategy-summary>div+div{border-left:1px solid #d7e1dd}.strategy-summary strong{font-size:38px;color:#16765b;margin:0 10px}.strategy-summary .danger{color:#a31317}.strategy-table{padding:14px 16px 36px;min-height:678px}.simulation-point{margin:16px 0}.simulation-results>div{padding:10px;border-bottom:1px solid #e1e8e4}.simulation-results pre{white-space:pre-wrap;font-size:12px}</style>
